INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0001-0001-0001-100000000001', 'Yirgacheffe Kochere', 'Ethiopia', 'Yirgacheffe', '🇪🇹', 'Washed', 'Light', '["jasmine","bergamot","lemon curd","stone fruit"]', 'Delicate and tea-like with a floral jasmine nose, vibrant bergamot acidity, and a silky lemon curd finish. One of the most aromatic coffees on the planet.', 'Kochere Washing Station', '1,750–2,200 m', 'October–December');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0002-0002-0002-200000000002', 'Guji Natural', 'Ethiopia', 'Guji Zone', '🇪🇹', 'Natural', 'Light', '["blueberry","dark cherry","dark chocolate","lavender"]', 'A wild, wine-like natural that bursts with blueberry compote and dark cherry on the palate, underscored by bittersweet dark chocolate and a lingering lavender note.', 'Shakiso Farmers Cooperative', '1,900–2,300 m', 'November–January');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0003-0003-0003-300000000003', 'Huila Honey', 'Colombia', 'Huila', '🇨🇴', 'Honey', 'Medium Light', '["peach","brown sugar","milk chocolate","apricot"]', 'Round and sweet with juicy peach and apricot, melting into brown sugar and milk chocolate through the mid-palate. The honey process adds a velvety body that rounds everything out beautifully.', 'La Esperanza Estate', '1,600–1,900 m', 'April–June');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0004-0004-0004-400000000004', 'Nariño Washed', 'Colombia', 'Nariño', '🇨🇴', 'Washed', 'Medium Light', '["red apple","caramel","hazelnut","lime zest"]', 'Crisp and bright with red apple and lime zest acidity, transitioning to creamy caramel sweetness and a gentle hazelnut finish. A textbook example of high-altitude Colombian excellence.', 'El Diviso Co-op', '1,800–2,100 m', 'May–August');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0005-0005-0005-500000000005', 'Nyeri AA', 'Kenya', 'Nyeri', '🇰🇪', 'Washed', 'Medium Light', '["blackcurrant","tomato","grapefruit","cranberry"]', 'Boldly structured with a distinctive blackcurrant and tomato-like savouriness, followed by grapefruit tartness and a clean cranberry finish. Intensely complex and unmistakably Kenyan.', 'Othaya Farmers Co-op Society', '1,650–1,850 m', 'October–December');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0006-0006-0006-600000000006', 'Kirinyaga Washed', 'Kenya', 'Kirinyaga', '🇰🇪', 'Washed', 'Medium', '["raspberry","lemon verbena","black tea","floral"]', 'More delicate than classic Nyeri lots, with raspberry jam sweetness, lemon verbena brightness, and a long floral aftertaste reminiscent of a fine Darjeeling.', 'Gichatha-ini Factory', '1,500–1,750 m', 'October–November');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0007-0007-0007-700000000007', 'Huehuetenango SHB', 'Guatemala', 'Huehuetenango', '🇬🇹', 'Washed', 'Medium', '["toffee","apple","almond","dried apricot"]', 'A well-balanced, crowd-pleasing cup with toffee sweetness, crisp apple acidity, and a roasted almond nuttiness. The dried apricot note lingers warmly through the finish.', 'ASDECOHUE Co-op', '1,500–2,000 m', 'December–March');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0008-0008-0008-800000000008', 'Tarrazu Anaerobic', 'Costa Rica', 'Tarrazú', '🇨🇷', 'Anaerobic', 'Light', '["tropical fruit","passion fruit","hibiscus","grape"]', 'An adventurous anaerobic that leads with explosive passion fruit and tropical aromatics. Hibiscus tea acidity and a grape-skin finish make this one for the experimentally minded.', 'Finca La Pastora', '1,700–1,900 m', 'December–February');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0009-0009-0009-900000000009', 'Sumatra Mandheling', 'Indonesia', 'North Sumatra', '🇮🇩', 'Wet Hulled', 'Medium Dark', '["cedar","dark chocolate","earthy","tobacco"]', 'Full-bodied and syrupy, with distinctive earthy cedar and tobacco notes underscored by bittersweet dark chocolate. The wet-hulled process gives this an unmistakably Indonesian character.', 'Wahana Estate', '1,200–1,500 m', 'June–October');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0010-0010-0010-A00000000010', 'Geisha Natural', 'Panama', 'Boquete', '🇵🇦', 'Natural', 'Light', '["peach nectar","orange blossom","white tea","honey"]', 'The legendary Geisha varietal at its most expressive. Peach nectar and orange blossom perfume the cup, with white tea delicacy and a long honey sweetness that simply refuses to fade.', 'Hacienda La Esmeralda', '1,600–1,900 m', 'March–April');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0011-0011-0011-B00000000011', 'Kayanza Washed', 'Burundi', 'Kayanza', '🇧🇮', 'Washed', 'Light', '["red plum","blood orange","brown sugar","clean"]', 'Bright and clean with red plum sweetness, blood orange acidity, and a comforting brown sugar finish. Exceptional clarity and sweetness make this a great introduction to East African coffees.', 'Mpanga Washing Station', '1,800–2,000 m', 'April–June');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0012-0012-0012-C00000000012', 'Nyungwe Honey', 'Rwanda', 'Nyungwe Forest', '🇷🇼', 'Honey', 'Medium Light', '["caramel apple","nectarine","vanilla","floral"]', 'Soft and fruit-forward, with caramel apple and nectarine sweetness balanced by a subtle vanilla creaminess. The honey process adds texture without losing the natural clarity of the varietal.', 'Kinini Washing Station', '1,700–2,100 m', 'March–May');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0013-0013-0013-D00000000013', 'Cajamarca Natural', 'Peru', 'Cajamarca', '🇵🇪', 'Natural', 'Medium', '["strawberry","molasses","walnut","milk chocolate"]', 'A rich, fruit-forward natural from Peru''s northern highlands. Fresh strawberry and molasses sweetness lead, with a walnut and milk chocolate backbone that makes it an ideal everyday drinker.', 'CENFROCAFE Co-op', '1,400–1,900 m', 'May–July');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0014-0014-0014-E00000000014', 'Marcala Carbonic', 'Honduras', 'La Paz (Marcala)', '🇭🇳', 'Carbonic Maceration', 'Light', '["strawberry soda","rose","guava","lime"]', 'A wildly experimental carbonic maceration with strawberry soda aromatics and rose petal sweetness. Guava and lime acidity make it effervescent and unlike anything else in the bag. Best black.', 'Finca Santa Rosa', '1,400–1,700 m', 'November–February');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0015-0015-0015-F00000000015', 'Chiapas Oaxaca Blend', 'Mexico', 'Chiapas / Oaxaca', '🇲🇽', 'Washed', 'Medium', '["dark chocolate","orange peel","cinnamon","toasted almond"]', 'A comforting blend of two great Mexican regions. Dark chocolate and toasted almond dominate, with a bright orange peel top note and a whisper of cinnamon that makes it perfect for the morning.', 'CESMACH Co-op', '1,100–1,600 m', 'November–February');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season) VALUES ('B1C2D3E4-0016-0016-0016-000000000016', 'Mokha Port Natural', 'Yemen', 'Haraz Mountains', '🇾🇪', 'Natural', 'Medium', '["dried fig","tamarind","cacao nib","aged wood"]', 'An ancient coffee with a story to match. Dried fig sweetness, tamarind tartness, and cacao nib depth are woven through a woody, almost smoky base that speaks to centuries of unbroken cultivation.', 'Al-Qafari Farm', '1,500–2,500 m', 'October–November');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1001-0000-0000-000000000001', 'Roast', 'Middellandplein 21B, 3021 BV Rotterdam', 51.91808, 4.45785, 'Coffee Shop', 4.8, '[{"day":"Monday","hours":"Closed"},{"day":"Tuesday","hours":"8:30 AM – 5:00 PM"},{"day":"Wednesday","hours":"8:30 AM – 5:00 PM"},{"day":"Thursday","hours":"8:30 AM – 5:00 PM"},{"day":"Friday","hours":"8:30 AM – 5:00 PM"},{"day":"Saturday","hours":"9:30 AM – 5:00 PM"},{"day":"Sunday","hours":"10:00 AM – 5:00 PM"}]', 'Roasts in-house on a Probat drum, rotating single-origins with a clean, classic Nordic-leaning profile.', 'An industrial-chic roastery in Scheepvaartkwartier, a benchmark for third-wave coffee in Rotterdam and one of the most photographed cafés in the city.', '["Single Origin","Work-Friendly","Outdoor Seating"]', 'ChIJEa7fflI1xEcRJFAP3WRDpWA');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1002-0000-0000-000000000002', 'Cafecito Meent', 'Meent 52, 3011 JM Rotterdam', 51.92279, 4.48413, 'Coffee Shop', 4.5, '[{"day":"Monday","hours":"7:00 AM – 6:00 PM"},{"day":"Tuesday","hours":"7:00 AM – 6:00 PM"},{"day":"Wednesday","hours":"7:00 AM – 6:00 PM"},{"day":"Thursday","hours":"7:00 AM – 6:00 PM"},{"day":"Friday","hours":"7:00 AM – 6:00 PM"},{"day":"Saturday","hours":"9:00 AM – 6:00 PM"},{"day":"Sunday","hours":"9:00 AM – 6:00 PM"}]', NULL, 'A small, buzzing espresso bar on Meent — famous for its Cuban-sandwich lunches, sharp flat whites and a rotating bean list.', '["Specialty Food","Alt Milk","Work-Friendly"]', 'ChIJrTPJ4eozxEcRB85FDCjHxjE');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1003-0000-0000-000000000003', 'Schot Coffee Roasters', 'Pelgrimsstraat 5C, 3029 PA Rotterdam', 51.9051, 4.444, 'Coffee Shop', 4.8, '[{"day":"Monday","hours":"Closed"},{"day":"Tuesday","hours":"Closed"},{"day":"Wednesday","hours":"9:00 AM – 5:00 PM"},{"day":"Thursday","hours":"9:00 AM – 5:00 PM"},{"day":"Friday","hours":"9:00 AM – 5:00 PM"},{"day":"Saturday","hours":"9:00 AM – 5:00 PM"},{"day":"Sunday","hours":"10:00 AM – 5:00 PM"}]', 'Father-and-son micro-roastery dialling in light-to-medium roasts on a small Giesen, with a strong focus on seasonal African lots.', 'A tucked-away roastery-café in the Agniesebuurt — open, bright, and favoured by Rotterdam''s coffee geeks for the rotating V60 menu.', '["Single Origin","Pet Friendly"]', 'ChIJK3_KMI41xEcR0k-mWdnbB2A');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1004-0000-0000-000000000004', 'Ripsnorter', 'Mariniersweg 65, 3011 NG Rotterdam', 51.92297, 4.48895, 'Coffee Shop', 4.7, '[{"day":"Monday","hours":"8:00 AM – 4:00 PM"},{"day":"Tuesday","hours":"Closed"},{"day":"Wednesday","hours":"8:00 AM – 4:00 PM"},{"day":"Thursday","hours":"8:00 AM – 4:00 PM"},{"day":"Friday","hours":"8:00 AM – 4:00 PM"},{"day":"Saturday","hours":"8:00 AM – 4:00 PM"},{"day":"Sunday","hours":"8:00 AM – 4:00 PM"}]', NULL, 'A warm neighbourhood espresso bar on Nieuwe Binnenweg — changing guest roasters, a short natural-wine list, and the city''s friendliest baristas.', '["Alt Milk","Pet Friendly","Work-Friendly"]', 'ChIJE4KGNnszxEcRi5nJwiDvmoM');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1005-0000-0000-000000000005', 'unfiltered', 'Van Oldenbarneveltstraat 125A, 3012 GT Rotterdam', 51.91905, 4.47322, 'Coffee Shop', 3.6, '[{"day":"Monday","hours":"9:00 AM – 5:00 PM"},{"day":"Tuesday","hours":"9:00 AM – 5:00 PM"},{"day":"Wednesday","hours":"9:00 AM – 5:00 PM"},{"day":"Thursday","hours":"9:00 AM – 5:00 PM"},{"day":"Friday","hours":"9:00 AM – 5:00 PM"},{"day":"Saturday","hours":"9:00 AM – 5:00 PM"},{"day":"Sunday","hours":"9:00 AM – 5:00 PM"}]', 'Works with European micro-roasters on a rotation; expect a lot from Friedhats, April and Manhattan Coffee Roasters.', 'A minimalist brew bar on Nieuwe Binnenweg — all white tile, Hario V60s and single-origin filters. Go for the slow-bar experience.', '["Single Origin","Work-Friendly"]', 'ChIJPUou-rc1xEcRefie7KTzhwo');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1006-0000-0000-000000000006', 'Espressobar Kopi Soesoe', 'Sumatraweg 15, 3072 ZP Rotterdam', 51.90118, 4.48427, 'Coffee Shop', 4.7, '[{"day":"Monday","hours":"Closed"},{"day":"Tuesday","hours":"Closed"},{"day":"Wednesday","hours":"8:30 AM – 4:30 PM"},{"day":"Thursday","hours":"8:30 AM – 4:30 PM"},{"day":"Friday","hours":"8:30 AM – 4:30 PM"},{"day":"Saturday","hours":"8:30 AM – 5:30 PM"},{"day":"Sunday","hours":"8:30 AM – 5:30 PM"}]', NULL, 'A tiny, Indonesian-inflected espresso bar on the Kralingen side of the dike. Flat whites, homemade cookies, and a warm welcome.', '["Alt Milk","Specialty Food","Pet Friendly"]', 'ChIJZV6JLXw0xEcRygjOVge5-uk');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1007-0000-0000-000000000007', 'Sound Kitchen', 'Samuel Soesmanstraat 52, 3015 GL Rotterdam', 51.90851, 4.4644, 'Coffee Shop', 5, '[{"day":"Monday","hours":"8:00 AM – 6:00 PM"},{"day":"Tuesday","hours":"8:00 AM – 6:00 PM"},{"day":"Wednesday","hours":"8:00 AM – 6:00 PM"},{"day":"Thursday","hours":"8:00 AM – 6:00 PM"},{"day":"Friday","hours":"8:00 AM – 6:00 PM"},{"day":"Saturday","hours":"8:00 AM – 6:00 PM"},{"day":"Sunday","hours":"8:00 AM – 6:00 PM"}]', NULL, 'A music-loving all-day café and kitchen — strong brunch menu, Man Met Bril beans on espresso, and vinyl always on the turntable.', '["Specialty Food","Alt Milk","Work-Friendly"]', 'ChIJuViTsYc1xEcRnY-YcuEKsLw');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1008-0000-0000-000000000008', 'Harvest Cafe & Bakery', 'Glashaven 105, 3011 XJ Rotterdam', 51.91575, 4.4858, 'Coffee Shop', 4.6, '[{"day":"Monday","hours":"9:00 AM – 4:00 PM"},{"day":"Tuesday","hours":"Closed"},{"day":"Wednesday","hours":"9:00 AM – 4:00 PM"},{"day":"Thursday","hours":"9:00 AM – 4:00 PM"},{"day":"Friday","hours":"9:00 AM – 4:00 PM"},{"day":"Saturday","hours":"9:00 AM – 5:00 PM"},{"day":"Sunday","hours":"9:00 AM – 5:00 PM"}]', NULL, 'A bright café-bakery where the sourdough and cinnamon buns are as considered as the coffee. Family-run and almost always busy on weekends.', '["Specialty Food","Alt Milk","Outdoor Seating"]', 'ChIJ-9W5ml0zxEcRjFfHU0lcdEI');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1009-0000-0000-000000000009', 'Hopper Noord', 'Zwaanshals 474, 3035 KS Rotterdam', 51.93202, 4.48574, 'Coffee Shop', 4.2, '[{"day":"Monday","hours":"9:00 AM – 6:00 PM"},{"day":"Tuesday","hours":"9:00 AM – 6:00 PM"},{"day":"Wednesday","hours":"9:00 AM – 6:00 PM"},{"day":"Thursday","hours":"9:00 AM – 6:00 PM"},{"day":"Friday","hours":"9:00 AM – 6:00 PM"},{"day":"Saturday","hours":"10:00 AM – 6:00 PM"},{"day":"Sunday","hours":"10:00 AM – 6:00 PM"}]', NULL, 'The Oude Noorden outpost of Hopper — a bright, high-ceilinged café that doubles as a local office for freelancers. Great lunches, solid espresso.', '["Specialty Food","Work-Friendly","Alt Milk"]', 'ChIJpeuTC1QzxEcRxR4RyCkeACk');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1010-0000-0000-00000000000A', 'Man Met Bril Koffie', 'Vijverhofstraat 70, 3032 SN Rotterdam', 51.93044, 4.47413, 'Coffee Shop', 4.5, '[{"day":"Monday","hours":"7:00 AM – 5:00 PM"},{"day":"Tuesday","hours":"7:00 AM – 5:00 PM"},{"day":"Wednesday","hours":"7:00 AM – 5:00 PM"},{"day":"Thursday","hours":"7:00 AM – 5:00 PM"},{"day":"Friday","hours":"7:00 AM – 5:00 PM"},{"day":"Saturday","hours":"8:00 AM – 6:00 PM"},{"day":"Sunday","hours":"8:00 AM – 6:00 PM"}]', 'Philip Reade''s roastery, housed under the old railway viaduct in Agniesebuurt. One of the most respected roasters in the Netherlands.', 'Rotterdam''s signature roaster — iconic viaduct location, friendly team, and beans that appear on menus across the country.', '["Single Origin","Outdoor Seating","Work-Friendly"]', 'ChIJb6vbOEUzxEcRdrhqH1MtuVM');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1011-0000-0000-00000000000B', 'Man Met Bril Koffie — Hotel New York', 'Koninginnenhoofd 1, 3072 AD Rotterdam', 51.90402, 4.48434, 'Coffee Shop', 4.7, '[{"day":"Monday","hours":"8:00 AM – 6:00 PM"},{"day":"Tuesday","hours":"8:00 AM – 6:00 PM"},{"day":"Wednesday","hours":"8:00 AM – 6:00 PM"},{"day":"Thursday","hours":"8:00 AM – 6:00 PM"},{"day":"Friday","hours":"8:00 AM – 6:00 PM"},{"day":"Saturday","hours":"8:00 AM – 6:00 PM"},{"day":"Sunday","hours":"8:00 AM – 6:00 PM"}]', 'Serves Man Met Bril''s rotating roasts on La Marzocco.', 'The Man Met Bril bar tucked inside Hotel New York on the Kop van Zuid — stunning water views and a full filter menu.', '["Single Origin","Outdoor Seating","Specialty Food"]', NULL);
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1012-0000-0000-00000000000C', 'Giraffe Coffee Bar & Academy', 'Hoogstraat 46A, 3011 PS Rotterdam', 51.9227, 4.49339, 'Coffee Shop', 4.6, '[{"day":"Monday","hours":"8:00 AM – 5:00 PM"},{"day":"Tuesday","hours":"8:00 AM – 5:00 PM"},{"day":"Wednesday","hours":"8:00 AM – 5:00 PM"},{"day":"Thursday","hours":"8:00 AM – 5:00 PM"},{"day":"Friday","hours":"8:00 AM – 5:00 PM"},{"day":"Saturday","hours":"9:00 AM – 5:00 PM"},{"day":"Sunday","hours":"Closed"}]', NULL, 'A combined bar and training academy — the team here has coached multiple Dutch Barista Championship finalists. Ask about latte art classes.', '["Single Origin","Work-Friendly","Alt Milk"]', 'ChIJw4a_69ozxEcR_q8nu39U1pU');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1013-0000-0000-00000000000D', 'Evermore', 'Coolhaven 158A, 3024 AM Rotterdam', 51.90755, 4.45506, 'Coffee Shop', 4.8, '[{"day":"Monday","hours":"Closed"},{"day":"Tuesday","hours":"Closed"},{"day":"Wednesday","hours":"10:00 AM – 1:00 PM"},{"day":"Thursday","hours":"10:00 AM – 1:00 PM"},{"day":"Friday","hours":"10:00 AM – 1:00 PM"},{"day":"Saturday","hours":"10:00 AM – 4:00 PM"},{"day":"Sunday","hours":"10:00 AM – 4:00 PM"}]', NULL, 'A plant-filled central café with a short, precise coffee menu and a loyal lunch crowd from the surrounding offices.', '["Specialty Food","Work-Friendly","Alt Milk"]', 'ChIJk4aLOpI0xEcRbRVaawOi-fc');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1014-0000-0000-00000000000E', 'No 10 Coffee', 'Hoogstraat 47A, 3011 PG Rotterdam', 51.9229, 4.4934, 'Coffee Shop', 4.4, '[{"day":"Monday","hours":"9:00 AM – 5:00 PM"},{"day":"Tuesday","hours":"9:00 AM – 5:00 PM"},{"day":"Wednesday","hours":"9:00 AM – 5:00 PM"},{"day":"Thursday","hours":"9:00 AM – 5:00 PM"},{"day":"Friday","hours":"9:00 AM – 5:00 PM"},{"day":"Saturday","hours":"9:00 AM – 5:00 PM"},{"day":"Sunday","hours":"9:00 AM – 5:00 PM"}]', NULL, 'A cosy espresso bar in Rotterdam''s gallery district. Great cortados and enough window seats for an afternoon''s reading.', '["Alt Milk","Work-Friendly","Pet Friendly"]', 'ChIJXz258CczxEcRJT6HPpac90Y');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1015-0000-0000-00000000000F', '33rd Street Coffee', 'Kleiweg 109A, 3051 GL Rotterdam', 51.94544, 4.47879, 'Coffee Shop', 4.7, '[{"day":"Monday","hours":"8:00 AM – 6:00 PM"},{"day":"Tuesday","hours":"8:00 AM – 6:00 PM"},{"day":"Wednesday","hours":"8:00 AM – 6:00 PM"},{"day":"Thursday","hours":"8:00 AM – 6:00 PM"},{"day":"Friday","hours":"8:00 AM – 6:00 PM"},{"day":"Saturday","hours":"9:00 AM – 6:00 PM"},{"day":"Sunday","hours":"9:00 AM – 5:00 PM"}]', NULL, 'A New-York-styled neighbourhood café with bagels, drip brew and a friendly, unfussy approach to specialty coffee.', '["Specialty Food","Work-Friendly","Alt Milk"]', 'ChIJiYWri6rLxUcRUrC1dXo-gNA');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1016-0000-0000-000000000010', 'SOCOCO Specialty Coffee', 'Schiemond 20, 3024 EE Rotterdam', 51.90305, 4.44969, 'Coffee Shop', 4.9, '[{"day":"Monday","hours":"Closed"},{"day":"Tuesday","hours":"8:30 AM – 4:00 PM"},{"day":"Wednesday","hours":"8:30 AM – 4:00 PM"},{"day":"Thursday","hours":"8:30 AM – 4:00 PM"},{"day":"Friday","hours":"8:30 AM – 4:00 PM"},{"day":"Saturday","hours":"9:30 AM – 4:00 PM"},{"day":"Sunday","hours":"10:00 AM – 4:00 PM"}]', 'Part of the SOCOCO social-enterprise project. Roasts in small batches and trains baristas from the local community.', 'A harbourside filter bar in Delfshaven''s Schiemond — serious about brewing, with weekly cuppings open to the public.', '["Single Origin","Outdoor Seating","Work-Friendly"]', 'ChIJJ7xkOrY1xEcR9Du6TU63zF4');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1017-0000-0000-000000000011', 'SOCOCO W70 — Social Coffeebar', 'Weena 70, 3012 CM Rotterdam', 51.92368, 4.47552, 'Coffee Shop', 4.5, '[{"day":"Monday","hours":"8:30 AM – 5:00 PM"},{"day":"Tuesday","hours":"8:30 AM – 5:00 PM"},{"day":"Wednesday","hours":"8:30 AM – 5:00 PM"},{"day":"Thursday","hours":"8:30 AM – 5:00 PM"},{"day":"Friday","hours":"8:30 AM – 5:00 PM"},{"day":"Saturday","hours":"Closed"},{"day":"Sunday","hours":"Closed"}]', 'Serves SOCOCO Specialty Coffee from the Schiemond roastery.', 'The business-district sibling of SOCOCO — quick, consistent espresso for Weena commuters and a purposeful social mission.', '["Work-Friendly","Alt Milk","Single Origin"]', 'ChIJFQ0gJLE1xEcRlUDirZL8T08');
